eights = [(0, 4), (0, 9), (1, 0), (4, 2), (5, 10), (6, 4), (8, 8), (9, 9), (10, 2), (10, 5)]

def section_from_pos(r, c):
    """Map input position to output 3x3 section"""
    if r <= 2:
        sec_r = 0
    elif r <= 6:
        sec_r = 1
    else:
        sec_r = 2

    if c <= 2:
        sec_c = 0
    elif c <= 6:
        sec_c = 1
    else:
        sec_c = 2

    return (sec_r, sec_c)

